import React from 'react';
import PropTypes from 'prop-types';
import styled from 'styled-components';
import { theme, media } from '@styles';
import useCountUp from '@hooks/useCountUp';

const StyledCounter = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
`;

const StyledNumber = styled.span`
  font-size: ${props => props.$size || '48px'};
  font-weight: 600;
  color: var(--color-accent);
  font-family: ${theme.fonts.SFMono};
  line-height: 1;

  ${media.tablet`font-size: ${props => props.$size ? `calc(${props.$size} * 0.8)` : '40px'};`}
  ${media.phablet`font-size: ${props => props.$size ? `calc(${props.$size} * 0.7)` : '32px'};`}
`;

const StyledLabel = styled.span`
  font-size: ${theme.fontSizes.md};
  color: var(--color-text-light);
  margin-top: 8px;

  ${media.phablet`font-size: ${theme.fontSizes.sm};`}
`;

const StyledSuffix = styled.span`
  font-size: ${props => props.$size || '48px'};
  font-weight: 600;
  color: var(--color-accent);
  font-family: ${theme.fonts.SFMono};

  ${media.tablet`font-size: ${props => props.$size ? `calc(${props.$size} * 0.8)` : '40px'};`}
  ${media.phablet`font-size: ${props => props.$size ? `calc(${props.$size} * 0.7)` : '32px'};`}
`;

/**
 * Animated counter component that counts up when scrolled into view
 */
const AnimatedCounter = ({
  end,
  label,
  suffix = '',
  prefix = '',
  duration = 2000,
  size,
  className,
}) => {
  const { count, ref } = useCountUp(end, duration);

  return (
    <StyledCounter ref={ref} className={className}>
      <div>
        {prefix && <StyledSuffix $size={size}>{prefix}</StyledSuffix>}
        <StyledNumber $size={size}>{count.toLocaleString()}</StyledNumber>
        {suffix && <StyledSuffix $size={size}>{suffix}</StyledSuffix>}
      </div>
      {label && <StyledLabel>{label}</StyledLabel>}
    </StyledCounter>
  );
};

AnimatedCounter.propTypes = {
  end: PropTypes.number.isRequired,
  label: PropTypes.string,
  suffix: PropTypes.string,
  prefix: PropTypes.string,
  duration: PropTypes.number,
  size: PropTypes.string,
  className: PropTypes.string,
};

export default AnimatedCounter;
