import React, { useState, useEffect, useCallback } from 'react';
import PropTypes from 'prop-types';
import { usePrefersReducedMotion } from '@hooks';
import { StyledSubtitle, StyledTypingSubtitle } from '../styles/hero-styles';

const HeroSubtitle = ({ subtitle, delay }) => {
    const [displayText, setDisplayText] = useState('');
    const [isTypingComplete, setIsTypingComplete] = useState(false);
    const prefersReducedMotion = usePrefersReducedMotion();

    const typeText = useCallback(() => {
        let currentIndex = 0;
        const typingSpeed = 50; // milliseconds per character

        const typeNextChar = () => {
            if (currentIndex < subtitle.length) {
                setDisplayText(subtitle.slice(0, currentIndex + 1));
                currentIndex++;
                setTimeout(typeNextChar, typingSpeed);
            } else {
                setIsTypingComplete(true);
            }
        };

        // Start typing after the initial delay
        const delayMs = parseInt(delay) || 300;
        setTimeout(typeNextChar, delayMs + 500);
    }, [subtitle, delay]);

    useEffect(() => {
        if (prefersReducedMotion) {
            setDisplayText(subtitle);
            setIsTypingComplete(true);
            return;
        }

        typeText();
    }, [subtitle, prefersReducedMotion, typeText]);

    // If user prefers reduced motion, show static text
    if (prefersReducedMotion) {
        return (
            <StyledSubtitle style={{ transitionDelay: delay }}>
                {subtitle}
            </StyledSubtitle>
        );
    }

    return (
        <StyledTypingSubtitle style={{ transitionDelay: delay }}>
            <span className="typing-text">{displayText}</span>
            {!isTypingComplete && <span className="cursor" />}
        </StyledTypingSubtitle>
    );
};

HeroSubtitle.propTypes = {
    subtitle: PropTypes.string.isRequired,
    delay: PropTypes.string.isRequired,
};

export default HeroSubtitle;
