import React, { useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import sr from '@utils/sr';
import { srConfig, github } from '@config';
import { StyledContainer, StyledFlexContainer, StyledContent, StyledPic } from '../styles/about-styles';
import Heading from '../subsections/Heading';
import Avatar from '../subsections/Avatar';

const About = ({ data }) => {
  const { frontmatter, html } = data[0].node;
  const { title, skills, avatar } = frontmatter;
  const revealContainer = useRef(null);

  useEffect(() => sr.reveal(revealContainer.current, srConfig()), []);

  return (
    <StyledContainer id="about" ref={revealContainer}>
      <Heading title={title} />
      <StyledFlexContainer>
        <StyledContent dangerouslySetInnerHTML={{ __html: html }} />
        <StyledPic>
          <Avatar github={github} avatar={avatar} />
        </StyledPic>
      </StyledFlexContainer>
    </StyledContainer>
  );
};

About.propTypes = {
  data: PropTypes.array.isRequired,
};

export default About;
