import React from 'react';
import PropTypes from 'prop-types';
import styled, { keyframes } from 'styled-components';
import { theme, media } from '@styles';

const fadeInUp = keyframes`
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

const StyledTimeline = styled.div`
  position: relative;
  padding: 20px 0;
  margin-left: 20px;

  ${media.tablet`margin-left: 10px;`}

  /* Vertical line */
  &::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 2px;
    background: linear-gradient(
      180deg,
      var(--color-accent) 0%,
      var(--color-bg-lightest) 100%
    );
  }
`;

const StyledTimelineItem = styled.div`
  position: relative;
  padding: 0 0 40px 40px;
  animation: ${fadeInUp} 0.5s ease forwards;
  animation-delay: ${props => props.$delay || 0}ms;
  opacity: 0;

  ${media.tablet`padding-left: 30px;`}

  @media (prefers-reduced-motion: reduce) {
    animation: none;
    opacity: 1;
  }

  &:last-child {
    padding-bottom: 0;
  }

  /* Timeline dot */
  &::before {
    content: '';
    position: absolute;
    left: -6px;
    top: 5px;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background-color: var(--color-bg);
    border: 2px solid var(--color-accent);
    z-index: 1;
  }

  /* Active/current item indicator */
  &[data-current="true"]::before {
    background-color: var(--color-accent);
    box-shadow: 0 0 0 4px var(--color-accent-tint);
  }
`;

const StyledTimelineHeader = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 10px;
`;

const StyledTitle = styled.h3`
  font-size: ${theme.fontSizes.xl};
  color: var(--color-text-lightest);
  margin: 0;

  ${media.phablet`font-size: ${theme.fontSizes.lg};`}
`;

const StyledCompany = styled.span`
  color: var(--color-accent);
  font-size: ${theme.fontSizes.lg};

  ${media.phablet`font-size: ${theme.fontSizes.md};`}

  a {
    color: inherit;
    text-decoration: none;

    &:hover {
      text-decoration: underline;
    }
  }
`;

const StyledDate = styled.span`
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.sm};
  color: var(--color-text-light);
  display: block;
  margin-bottom: 15px;

  ${media.phablet`font-size: ${theme.fontSizes.xs};`}
`;

const StyledDescription = styled.div`
  color: var(--color-text);
  font-size: ${theme.fontSizes.md};
  line-height: 1.6;

  ul {
    padding-left: 20px;
    margin: 0;
    list-style: none;

    li {
      position: relative;
      padding-left: 20px;
      margin-bottom: 8px;

      &::before {
        content: '▹';
        position: absolute;
        left: 0;
        color: var(--color-accent);
      }
    }
  }

  p {
    margin: 0 0 10px;
  }
`;

const StyledLocation = styled.span`
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.xs};
  color: var(--color-text-light);
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 10px;

  svg {
    width: 14px;
    height: 14px;
  }
`;

const StyledScore = styled.span`
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.xs};
  color: var(--color-accent);
  display: inline-block;
  background-color: var(--color-accent-tint);
  padding: 4px 10px;
  border-radius: ${theme.borderRadius};
  margin-bottom: 15px;
`;

const Timeline = ({ items, type = 'job' }) => {
  return (
    <StyledTimeline>
      {items.map((item, i) => {
        const { node } = item;
        const { frontmatter, html } = node;

        // Handle both job and education data structures
        const title = type === 'job' ? frontmatter.title : (frontmatter.programme || frontmatter.degree);
        const company = type === 'job' ? frontmatter.company : frontmatter.school;
        const url = frontmatter.url;
        const range = frontmatter.range;
        const location = frontmatter.location;
        const score = type === 'education' ? frontmatter.score : null;
        const isCurrent = range && range.toLowerCase().includes('present');

        return (
          <StyledTimelineItem key={i} $delay={i * 100} data-current={isCurrent}>
            <StyledTimelineHeader>
              <StyledTitle>{title}</StyledTitle>
              <StyledCompany>
                {url ? (
                  <a href={url} target="_blank" rel="nofollow noopener noreferrer">
                    @ {company}
                  </a>
                ) : (
                  `@ ${company}`
                )}
              </StyledCompany>
            </StyledTimelineHeader>

            <StyledDate>{range}</StyledDate>

            {location && (
              <StyledLocation>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z" />
                  <circle cx="12" cy="10" r="3" />
                </svg>
                {location}
              </StyledLocation>
            )}

            {score && <StyledScore>{score}</StyledScore>}

            <StyledDescription dangerouslySetInnerHTML={{ __html: html }} />
          </StyledTimelineItem>
        );
      })}
    </StyledTimeline>
  );
};

Timeline.propTypes = {
  items: PropTypes.array.isRequired,
  type: PropTypes.oneOf(['job', 'education']),
};

export default Timeline;
