import React from 'react';
import PropTypes from 'prop-types';
import {
    StyledTabContent,
    StyledJobTitle,
    StyledCompany,
    StyledJobDetails,
    StyledFeaturedImg,
    StyledTechList,
} from '../styles/jobs-styles';

const JobTabContent = ({ isActive, node, id, hidden }) => {
    const { frontmatter, html } = node;
    const { title, company, url, range, tech, logo } = frontmatter;

    return (
        <StyledTabContent
            isActive={isActive}
            id={id}
            role="tabpanel"
            aria-labelledby={id}
            tabIndex={isActive ? '0' : '-1'}
            hidden={hidden}
        >
            <div style={{ display: 'flex' }}>
                <div style={{ marginRight: '1.5rem' }}>
                    <StyledFeaturedImg image={logo.childImageSharp.gatsbyImageData} alt="logo" />
                </div>
                <div>
                    <StyledJobTitle>
                        <StyledCompany>
                            <a href={url} target="_blank" rel="nofollow noopener noreferrer">
                                {company}
                            </a>
                        </StyledCompany>
                        <br />
                        <span>{title}</span>
                    </StyledJobTitle>
                    <StyledJobDetails>
                        <span>{range}</span>
                    </StyledJobDetails>
                </div>
            </div>
            <div style={{ textAlign: 'justify' }} dangerouslySetInnerHTML={{ __html: html }} />
            {tech && (
                <StyledTechList>
                    {tech.map((techItem, i) => (
                        <li key={i}>{techItem}</li>
                    ))}
                </StyledTechList>
            )}
        </StyledTabContent>
    );
};

JobTabContent.propTypes = {
    isActive: PropTypes.bool.isRequired,
    node: PropTypes.object.isRequired,
    id: PropTypes.string.isRequired,
    hidden: PropTypes.bool.isRequired,
};

export default JobTabContent;
