import React, { useState, useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import sr from '@utils/sr';
import { srConfig } from '@config';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import { Heading } from '@styles';
import {
    StyledContainer,
    StyledTabs,
    StyledTabList,
    StyledHighlight,
    StyledTabContent,
    StyledGrid,
} from '../styles/skills-styles';
import TabButton from '../subsections/SkillTabButton';
import SkillItem from '../subsections/SkillItem';

const GRID_LIMIT = 9;

const Skills = ({ skillsData, skillOrder }) => {
    const [activeTabId, setActiveTabId] = useState(0);
    const [tabFocus, setTabFocus] = useState(null);
    const [skillsMap, setSkillsMap] = useState({});
    const tabs = useRef([]);
    const revealContainer = useRef(null);

    useEffect(() => sr.reveal(revealContainer.current, srConfig()), []);

    useEffect(() => {
        const skillsMap = {};

        Object.keys(skillOrder).forEach(category => {
            skillsMap[category] = [];
        });

        skillsData.forEach(({ node }) => {
            const { name, logo } = node.frontmatter;
            Object.keys(skillOrder).forEach(category => {
                if (skillOrder[category].includes(name)) {
                    skillsMap[category].push({ name, logo });
                }
            });
        });

        Object.keys(skillsMap).forEach(category => {
            skillsMap[category].sort(
                (a, b) => skillOrder[category].indexOf(a.name) - skillOrder[category].indexOf(b.name)
            );
        });

        setSkillsMap(skillsMap);
    }, [skillsData, skillOrder]);

    const focusTab = () => {
        if (tabs.current[tabFocus]) {
            tabs.current[tabFocus].focus();
        } else {
            if (tabFocus >= tabs.current.length) {
                setTabFocus(0);
            }
            if (tabFocus < 0) {
                setTabFocus(tabs.current.length - 1);
            }
        }
    };

    useEffect(() => focusTab(), [tabFocus]);

    const onKeyPressed = e => {
        if (e.keyCode === 38 || e.keyCode === 40) {
            e.preventDefault();
            if (e.keyCode === 40) {
                setTabFocus(tabFocus + 1);
            } else if (e.keyCode === 38) {
                setTabFocus(tabFocus - 1);
            }
        }
    };

    return (
        <StyledContainer id="skills" ref={revealContainer}>
            <Heading>Skills</Heading>
            <StyledTabs>
                <StyledTabList role="tablist" aria-label="Skills tabs" onKeyDown={e => onKeyPressed(e)}>
                    {skillsMap &&
                        Object.keys(skillsMap).map((category, i) => (
                            <li key={i}>
                                <TabButton
                                    isActive={activeTabId === i}
                                    onClick={() => setActiveTabId(i)}
                                    ref={el => (tabs.current[i] = el)}
                                    id={`tab-${i}`}
                                    tabIndex={activeTabId === i ? '0' : '-1'}
                                    category={category}
                                />
                            </li>
                        ))}
                    <StyledHighlight activeTabId={activeTabId} />
                </StyledTabList>

                {skillsMap &&
                    Object.keys(skillsMap).map((category, i) => (
                        <StyledTabContent
                            key={i}
                            isActive={activeTabId === i}
                            id={`panel-${i}`}
                            role="tabpanel"
                            aria-labelledby={`tab-${i}`}
                            tabIndex={activeTabId === i ? '0' : '-1'}
                            hidden={activeTabId !== i}>
                            <StyledGrid>
                                <TransitionGroup className="projects">
                                    {skillsMap[category] &&
                                        skillsMap[category].map((skill, i) => (
                                            <CSSTransition
                                                key={i}
                                                classNames="fadeup"
                                                timeout={i >= GRID_LIMIT ? (i - GRID_LIMIT) * 300 : 300}
                                                exit={false}>
                                                <SkillItem
                                                    key={i}
                                                    skill={skill}
                                                    delay={i >= GRID_LIMIT ? (i - GRID_LIMIT) * 100 : 0}
                                                />
                                            </CSSTransition>
                                        ))}
                                </TransitionGroup>
                            </StyledGrid>
                        </StyledTabContent>
                    ))}
            </StyledTabs>
        </StyledContainer>
    );
};

Skills.propTypes = {
    skillsData: PropTypes.array.isRequired,
    skillOrder: PropTypes.object.isRequired,
};

export default Skills;
