import React from 'react';
import PropTypes from 'prop-types';
import {
    StyledProject,
    StyledProjectInner,
    StyledFeaturedImg,
    StyledProjectName,
} from '../styles/skills-styles';

const SkillItem = ({ skill, delay }) => {
    const { name, logo } = skill;

    return (
        <StyledProject
            tabIndex="0"
            style={{
                transitionDelay: `${delay}ms`,
            }}>
            <StyledProjectInner>
                {logo && logo.childImageSharp && (
                    <StyledFeaturedImg
                        image={logo.childImageSharp.gatsbyImageData}
                        alt={name}
                    />
                )}
                <StyledProjectName>{name}</StyledProjectName>
            </StyledProjectInner>
        </StyledProject>
    );
};

SkillItem.propTypes = {
    skill: PropTypes.object.isRequired,
    delay: PropTypes.number.isRequired,
};

export default SkillItem;
