import React from 'react';
import PropTypes from 'prop-types';
import styled from 'styled-components';
import { theme, media } from '@styles';
import { FormattedIcon } from '@components/icons';
import Modal from './Modal';

const StyledContent = styled.div`
  padding: 40px;

  ${media.tablet`padding: 30px 25px;`}
  ${media.phablet`padding: 25px 20px;`}
`;

const StyledHeader = styled.div`
  margin-bottom: 25px;
`;

const StyledFolder = styled.div`
  color: var(--color-accent);
  margin-bottom: 15px;

  svg {
    width: 40px;
    height: 40px;
  }
`;

const StyledTitle = styled.h3`
  font-size: 28px;
  color: var(--color-text-lightest);
  margin: 0 0 15px 0;
  padding-right: 40px;

  ${media.tablet`font-size: 24px;`}
`;

const StyledLinks = styled.div`
  display: flex;
  gap: 15px;
`;

const StyledIconLink = styled.a`
  color: var(--color-text-light);
  padding: 5px;
  transition: ${theme.transition};

  &:hover {
    color: var(--color-accent);
  }

  svg {
    width: 22px;
    height: 22px;
  }
`;

const StyledDescription = styled.div`
  color: var(--color-text);
  font-size: ${theme.fontSizes.lg};
  line-height: 1.6;
  margin-bottom: 25px;

  p {
    margin: 0 0 15px;
  }

  a {
    color: var(--color-accent);
    text-decoration: underline;
  }

  ${media.phablet`font-size: ${theme.fontSizes.md};`}
`;

const StyledTechSection = styled.div`
  margin-top: 25px;
  padding-top: 25px;
  border-top: 1px solid var(--color-bg-lightest);
`;

const StyledTechLabel = styled.h4`
  color: var(--color-text-lightest);
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.sm};
  margin: 0 0 15px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
`;

const StyledTechList = styled.ul`
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  list-style: none;
  padding: 0;
  margin: 0;
`;

const StyledTechItem = styled.li`
  background-color: var(--color-bg);
  color: var(--color-accent);
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.xs};
  padding: 8px 12px;
  border-radius: 4px;
  border: 1px solid var(--color-bg-lightest);
`;

const StyledActions = styled.div`
  display: flex;
  gap: 15px;
  margin-top: 30px;
  flex-wrap: wrap;
`;

const StyledButton = styled.a`
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  background-color: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  border-radius: ${theme.borderRadius};
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.sm};
  text-decoration: none;
  transition: ${theme.transition};

  &:hover {
    background-color: var(--color-accent-tint);
  }

  svg {
    width: 18px;
    height: 18px;
  }
`;

const ProjectDetailModal = ({ isOpen, onClose, project }) => {
  if (!project) return null;

  const { frontmatter, html } = project;
  const { github, external, title, tech } = frontmatter;

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <StyledContent>
        <StyledHeader>
          <StyledFolder>
            <FormattedIcon name="Folder" />
          </StyledFolder>
          <StyledTitle>{title}</StyledTitle>
          <StyledLinks>
            {github && (
              <StyledIconLink
                href={github}
                target="_blank"
                rel="nofollow noopener noreferrer"
                aria-label="GitHub Repository">
                <FormattedIcon name="GitHub" />
              </StyledIconLink>
            )}
            {external && (
              <StyledIconLink
                href={external}
                target="_blank"
                rel="nofollow noopener noreferrer"
                aria-label="External Link">
                <FormattedIcon name="External" />
              </StyledIconLink>
            )}
          </StyledLinks>
        </StyledHeader>

        <StyledDescription dangerouslySetInnerHTML={{ __html: html }} />

        {tech && tech.length > 0 && (
          <StyledTechSection>
            <StyledTechLabel>Technologies Used</StyledTechLabel>
            <StyledTechList>
              {tech.map((item, i) => (
                <StyledTechItem key={i}>{item}</StyledTechItem>
              ))}
            </StyledTechList>
          </StyledTechSection>
        )}

        <StyledActions>
          {github && (
            <StyledButton
              href={github}
              target="_blank"
              rel="nofollow noopener noreferrer">
              <FormattedIcon name="GitHub" />
              View Source
            </StyledButton>
          )}
          {external && (
            <StyledButton
              href={external}
              target="_blank"
              rel="nofollow noopener noreferrer">
              <FormattedIcon name="External" />
              Visit Project
            </StyledButton>
          )}
        </StyledActions>
      </StyledContent>
    </Modal>
  );
};

ProjectDetailModal.propTypes = {
  isOpen: PropTypes.bool.isRequired,
  onClose: PropTypes.func.isRequired,
  project: PropTypes.object,
};

export default ProjectDetailModal;
