import React from 'react';
import PropTypes from 'prop-types';
import { FormattedIcon } from '@components/icons';
import {
    StyledProject,
    StyledProjectInner,
    StyledProjectHeader,
    StyledFolder,
    StyledProjectLinks,
    StyledIconLink,
    StyledProjectName,
    StyledProjectDescription,
    StyledTechList,
    StyledExpandButton,
} from '../styles/projects-styles';

const ProjectItem = React.forwardRef(({ node, delay, onExpand }, ref) => {
    const { frontmatter, html } = node;
    const { github, external, title, tech } = frontmatter;

    return (
        <StyledProject
            ref={ref}
            tabIndex="0"
            style={{
                transitionDelay: `${delay}ms`,
            }}>
            <StyledProjectInner>
                <header>
                    <StyledProjectHeader>
                        <StyledFolder>
                            <FormattedIcon name="Folder" />
                        </StyledFolder>
                        <StyledProjectLinks>
                            {github && (
                                <StyledIconLink
                                    href={github}
                                    target="_blank"
                                    rel="nofollow noopener noreferrer"
                                    aria-label="GitHub Link">
                                    <FormattedIcon name="GitHub" />
                                </StyledIconLink>
                            )}
                            {external && (
                                <StyledIconLink
                                    href={external}
                                    target="_blank"
                                    rel="nofollow noopener noreferrer"
                                    aria-label="External Link">
                                    <FormattedIcon name="External" />
                                </StyledIconLink>
                            )}
                        </StyledProjectLinks>
                    </StyledProjectHeader>
                    <StyledProjectName>{title}</StyledProjectName>
                    <StyledProjectDescription dangerouslySetInnerHTML={{ __html: html }} />
                </header>
                <footer>
                    {tech && (
                        <StyledTechList>
                            {tech.map((item, i) => (
                                <li key={i}>{item}</li>
                            ))}
                        </StyledTechList>
                    )}
                    {onExpand && (
                        <StyledExpandButton onClick={onExpand} aria-label="View project details">
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <polyline points="15 3 21 3 21 9" />
                                <polyline points="9 21 3 21 3 15" />
                                <line x1="21" y1="3" x2="14" y2="10" />
                                <line x1="3" y1="21" x2="10" y2="14" />
                            </svg>
                            View Details
                        </StyledExpandButton>
                    )}
                </footer>
            </StyledProjectInner>
        </StyledProject>
    );
});

ProjectItem.propTypes = {
    node: PropTypes.object.isRequired,
    delay: PropTypes.number.isRequired,
    onExpand: PropTypes.func,
};

export default ProjectItem;
