import React from 'react';
import PropTypes from 'prop-types';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import { FormattedIcon } from '@components/icons';
import {
    StyledProject,
    StyledProjectInner,
    StyledProjectHeader,
    StyledFolder,
    StyledProjectLinks,
    StyledIconLink,
    StyledProjectName,
    StyledProjectInstitute,
    StyledProjectDescription,
    StyledTechList,
} from '../styles/certifications-styles';

const CertificationGrid = ({ projects, revealProjects, gridLimit }) => (
    <TransitionGroup className="projects">
        {projects &&
            projects.map(({ node }, i) => {
                const { frontmatter, html } = node;
                const { course, institute, company, github, external, tech } = frontmatter;

                return (
                    <CSSTransition
                        key={i}
                        classNames="fadeup"
                        timeout={i >= gridLimit ? (i - gridLimit) * 300 : 300}
                        exit={false}>
                        <StyledProject
                            key={i}
                            ref={el => (revealProjects.current[i] = el)}
                            tabIndex="0"
                            style={{
                                transitionDelay: `${i >= gridLimit ? (i - gridLimit) * 100 : 0}ms`,
                            }}>
                            <StyledProjectInner>
                                <header>
                                    <StyledProjectHeader>
                                        <StyledFolder>
                                            <FormattedIcon name="Folder" />
                                        </StyledFolder>
                                        <StyledProjectLinks>
                                            {github && (
                                                <StyledIconLink
                                                    href={github}
                                                    target="_blank"
                                                    rel="nofollow noopener noreferrer"
                                                    aria-label="GitHub Link">
                                                    <FormattedIcon name="GitHub" />
                                                </StyledIconLink>
                                            )}
                                            {external && (
                                                <StyledIconLink
                                                    href={external}
                                                    target="_blank"
                                                    rel="nofollow noopener noreferrer"
                                                    aria-label="External Link">
                                                    <FormattedIcon name="External" />
                                                </StyledIconLink>
                                            )}
                                        </StyledProjectLinks>
                                    </StyledProjectHeader>
                                    <StyledProjectName>{course}</StyledProjectName>
                                    <StyledProjectInstitute>{institute}</StyledProjectInstitute>
                                    <StyledProjectDescription dangerouslySetInnerHTML={{ __html: html }} />
                                </header>
                                <footer>
                                    {tech && (
                                        <StyledTechList>
                                            {tech.map((tech, i) => (
                                                <li key={i}>{tech}</li>
                                            ))}
                                        </StyledTechList>
                                    )}
                                </footer>
                            </StyledProjectInner>
                        </StyledProject>
                    </CSSTransition>
                );
            })}
    </TransitionGroup>
);

CertificationGrid.propTypes = {
    projects: PropTypes.array.isRequired,
    revealProjects: PropTypes.object.isRequired,
    gridLimit: PropTypes.number.isRequired,
};

export default CertificationGrid;