import React from 'react';
import PropTypes from 'prop-types';
import {
    StyledTabContent,
    StyledEducationTitle,
    StyledCompany,
    StyledEducationDetails,
    StyledFeaturedImg,
} from '../styles/education-styles';

const EducationTabContent = ({ isActive, node, id, hidden }) => {
    const { frontmatter, html } = node;
    const { school, programme, score, url, range, logo } = frontmatter;

    return (
        <StyledTabContent
            isActive={isActive}
            id={id}
            role="tabpanel"
            aria-labelledby={id}
            tabIndex={isActive ? '0' : '-1'}
            hidden={hidden}
        >
            <div style={{ display: 'flex' }}>
                <div style={{ marginRight: '1.5rem' }}>
                    <StyledFeaturedImg image={logo.childImageSharp.gatsbyImageData} alt="logo" />
                </div>
                <div>
                    <StyledEducationTitle>
                        <StyledCompany>
                            <a href={url} target="_blank" rel="nofollow noopener noreferrer">
                                {school}
                            </a>
                        </StyledCompany>
                        <br />
                        <span>{programme}</span>
                    </StyledEducationTitle>
                    <StyledEducationDetails>
                        <span>{range}</span>
                        <br />
                        <span>{score}</span>
                    </StyledEducationDetails>
                </div>
            </div>
            <div dangerouslySetInnerHTML={{ __html: html }} />
        </StyledTabContent>
    );
};

EducationTabContent.propTypes = {
    isActive: PropTypes.bool.isRequired,
    node: PropTypes.object.isRequired,
    id: PropTypes.string.isRequired,
    hidden: PropTypes.bool.isRequired,
};

export default EducationTabContent;
